    public static function check($ip_address)
    {
        $ch = curl_init('http://ip-api.com/php/' . $ip_address);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $json = curl_exec($ch);
        curl_close($ch);

        return (object)unserialize($json);
    }

