    public static function patternPhone()
    {
        return self::patternPhoneStart() . "(9[976]\d|8[987530]\d|6[987]\d|5[90]\d|42\d|3[875]\d|2[98654321]\d|9[8543210]|8[6421]|6[6543210]|5[87654321]|4[987654310]|3[9643210]|2[70]|7|1)\d{4,20}$/";
    }
    public static function patternPhoneStart(bool $close = false)
    {
        $pattern = "/^(\+|00)". self::patternPhonePrefix();

        return $close ? $pattern."/" : $pattern;
    }

    public static function phoneOperator(string $phone, string $country, bool $allOperators = false): ?string
    {
        $opertorNumber = self::phoneOperatorNumber($phone, $country);
        $operators = [
            'CD' => [
                81 => 'VODACOM_DRC',
                82 => 'VODACOM_DRC',
                83 => 'VODACOM_DRC',
                84 => 'ORANGE_DRC',
                85 => 'ORANGE_DRC',
                89 => 'ORANGE_DRC',
                98 => 'AIRTEL_DRC',
                99 => 'AIRTEL_DRC',
                90 => 'AFRICELL_DRC',
                91 => 'AFRICELL_DRC',
            ]
        ];

        $all = array_key_exists($country, $operators) ? $operators[$country] : null;
        if ($allOperators) return $all;

        return array_key_exists($opertorNumber, $all) ? $all[$opertorNumber] : null;
    }
